// Speed graph and curve editing (11.11).
//
// The load-bearing test here is the cross-language one: `easing-reference.ts`
// is generated by running the *Rust* evaluator, so asserting this TypeScript
// reproduces it is what makes "one specification, two implementations"
// checkable rather than hopeful (invariant 27). The failure it prevents is a
// preview that eases differently from the engine — a lie about what goes to
// air, which is worse than showing nothing.

import { describe, expect, it } from "vitest";

import type { CubicBezier, KeyframeChannel, SceneKeyframe } from "@grapix/contracts";
import { CUSTOM_BEZIER_REFERENCE, EASING_REFERENCE } from "../src/easing-reference";
import {
  channelValueRange,
  easeAt,
  easingControlPoints,
  evaluateChannel,
} from "../src/timeline/easing";
import {
  bezierFromHandleDrag,
  buildSpeedGraph,
  yToValue,
} from "../src/timeline/speed-graph";
import type { TimelineViewport } from "../src/timeline/viewport";

function key(
  frame: number,
  value: number,
  easing: SceneKeyframe["easing"] = "linear",
  bezier?: CubicBezier,
): SceneKeyframe {
  return {
    frame: frame as unknown as bigint,
    value,
    easing,
    ...(bezier ? { bezier } : {}),
  };
}

function channel(keys: SceneKeyframe[]): KeyframeChannel {
  return { objectId: "card", property: "x", keys };
}

const viewport: TimelineViewport = {
  startFrame: 0,
  pixelsPerFrame: 6,
  width: 600,
  height: 160,
  scrollTop: 0,
  rowHeight: 22,
};

describe("the TypeScript easing mirrors Rust exactly", () => {
  it("reproduces every sample in the Rust-generated reference", () => {
    // Generated by `gx-contract-codegen` from gx_contracts::animation::ease_at.
    expect(EASING_REFERENCE.length).toBeGreaterThan(0);
    for (const sample of EASING_REFERENCE) {
      const mine = easeAt(sample.easing as SceneKeyframe["easing"], undefined, sample.t);
      expect(
        Math.abs(mine - sample.y),
        `${sample.easing} at t=${sample.t}: TS ${mine} vs Rust ${sample.y}`,
      ).toBeLessThan(1e-9);
    }
  });

  it("reproduces the custom-bezier reference, overshoot included", () => {
    const points = CUSTOM_BEZIER_REFERENCE.points as CubicBezier;
    let sawOvershoot = false;
    for (const sample of CUSTOM_BEZIER_REFERENCE.samples) {
      const mine = easeAt("custom-bezier", points, sample.t);
      expect(Math.abs(mine - sample.y)).toBeLessThan(1e-9);
      if (sample.y > 1) sawOvershoot = true;
    }
    // The fixture is deliberately an overshooting curve; if it stopped
    // overshooting the test would silently stop covering the case.
    expect(sawOvershoot).toBe(true);
  });

  it("reads named control points from the generated table, not a second list", () => {
    expect(easingControlPoints("ease-in")).toEqual({ x1: 0.42, y1: 0, x2: 1, y2: 1 });
    expect(easingControlPoints("ease-in-out")).toEqual({ x1: 0.42, y1: 0, x2: 0.58, y2: 1 });
  });
});

describe("channel evaluation", () => {
  it("interpolates, and holds flat outside the keyed range", () => {
    const c = channel([key(0, 0), key(100, 200)]);
    expect(evaluateChannel(c, 50)).toBe(100);
    expect(evaluateChannel(c, -10)).toBe(0);
    expect(evaluateChannel(c, 9_999)).toBe(200);
    expect(evaluateChannel(channel([]), 0)).toBeUndefined();
  });

  it("a hold steps rather than ramping", () => {
    const c = channel([key(0, 0, "hold"), key(100, 200)]);
    expect(evaluateChannel(c, 1)).toBe(0);
    expect(evaluateChannel(c, 99)).toBe(0);
    expect(evaluateChannel(c, 100)).toBe(200);
  });

  it("reports a value range that includes overshoot", () => {
    const overshoot: CubicBezier = { x1: 0.34, y1: 1.56, x2: 0.64, y2: 1 };
    const c = channel([key(0, 0, "custom-bezier", overshoot), key(100, 100)]);
    const range = channelValueRange(c);
    // A graph that clipped the overshoot would hide the thing the author
    // opened the curve editor to see.
    expect(range.max).toBeGreaterThan(100);
    const flat = channelValueRange(channel([key(0, 5), key(10, 5)]));
    expect(flat.max).toBeGreaterThan(flat.min);
  });
});

describe("speed graph", () => {
  it("costs the viewport, not the document", () => {
    const few = channel([key(0, 0), key(100, 100)]);
    const many = channel(
      Array.from({ length: 20_000 }, (_, index) => key(index * 5, index % 50)),
    );
    const small = buildSpeedGraph(few, viewport, 160, 100_000);
    const large = buildSpeedGraph(many, viewport, 160, 100_000);

    // One sample per visible pixel column in both cases.
    expect(small.polyline.length).toBe(large.polyline.length);
    expect(large.polyline.length).toBeLessThanOrEqual(Math.ceil(viewport.width) + 1);
    // Handles only for keys on screen: 600px at 6px/frame is ~100 frames.
    expect(large.keys.length).toBeLessThan(120);
  });

  it("places keys by value, with larger values higher on screen", () => {
    const graph = buildSpeedGraph(channel([key(0, 0), key(100, 100)]), viewport, 160, 100);
    const [low, high] = graph.keys;
    expect(low!.value).toBe(0);
    expect(high!.value).toBe(100);
    // Screen Y grows downward, so the larger value has the smaller Y.
    expect(high!.at.y).toBeLessThan(low!.at.y);
  });

  it("gives a draggable outgoing handle to every key but the last", () => {
    const graph = buildSpeedGraph(
      channel([key(0, 0, "ease-in-out"), key(50, 50, "ease-in-out"), key(100, 100)]),
      viewport,
      160,
      100,
    );
    expect(graph.keys[0]!.outHandle).toBeDefined();
    expect(graph.keys[1]!.outHandle).toBeDefined();
    // The last key has nothing to ease toward.
    expect(graph.keys[2]!.outHandle).toBeUndefined();
  });

  it("a hold has no handle, because it has no curve to shape", () => {
    const graph = buildSpeedGraph(
      channel([key(0, 0, "hold"), key(100, 100)]),
      viewport,
      160,
      100,
    );
    expect(graph.keys[0]!.outHandle).toBeUndefined();
  });

  it("a dragged handle round-trips into a control point the contract accepts", () => {
    const from = key(0, 0, "ease-in-out");
    const to = key(100, 100);
    const graph = buildSpeedGraph(channel([from, to]), viewport, 160, 100);
    const handle = graph.keys[0]!.outHandle!;

    // Dragging nowhere reproduces the curve it started from.
    const same = bezierFromHandleDrag(from, to, handle, viewport, graph.min, graph.max, 160);
    expect(same.x1).toBeCloseTo(0.42, 2);

    // Dragged far right and low, x1 is clamped into 0–1 as validate_key
    // demands, while y1 stays free so overshoot remains expressible.
    const dragged = bezierFromHandleDrag(
      from,
      to,
      { x: 100_000, y: -5_000 },
      viewport,
      graph.min,
      graph.max,
      160,
    );
    expect(dragged.x1).toBeLessThanOrEqual(1);
    expect(dragged.x1).toBeGreaterThanOrEqual(0);
    expect(dragged.y1).toBeGreaterThan(1);
  });

  it("maps screen Y back to a value", () => {
    expect(yToValue(0, 0, 100, 200)).toBe(100);
    expect(yToValue(200, 0, 100, 200)).toBe(0);
    expect(yToValue(100, 0, 100, 200)).toBe(50);
  });
});
